:is(body.dark-mode, html.dark-mode, html.dark, body.dark, .theme-dark, .dark-theme, [data-theme="dark"], [data-mode="dark"], [data-color-scheme="dark"]) :is(#chat-detail-screen, .chat-detail-screen){
