/* ===== 通话美化from 🍓小Q怡🍫 宝宝 ===== */
:root {
  --call-avatar-image: url('https://i.postimg.cc/L8NrbF7f/wu-biao-ti173-20260606111422.png');
  --call-text-me-cancel:   "已取消";
  --call-text-them-reject: "对方已取消";
  --call-text-connected:   "通话时长 ";
}

/* 📞 通话卡片主体容器（恢复微信标准尺寸比例） */
.msg-videocall-card {
  width: fit-content !important;
  min-width: 110px !important;           /* 👈 核心：设置微信标准最小宽度，告别干瘪小卡片 */
  max-width: 240px !important;
  padding: 9px 12px !important;          /* 👈 与普通气泡 9px 上下内边距完全对齐 */
  border-radius: 4px !important;
  box-shadow: none !important;
  border: none !important;
  display: flex !important;
  align-items: center !important;
  gap: 10px !important;                  /* 图标与文字舒适间距 */
  position: relative !important;
  cursor: default !important;
  background: var(--bubble-them-bg) !important;
  color: var(--bubble-them-color) !important; /* 默认跟随对方文字颜色 */
}

/* 我方发起的通话 */
.msg-me .msg-videocall-card {
  background: var(--bubble-me-bg) !important;
  color: var(--bubble-me-color) !important;  /* 👈 核心：我方文字与图标颜色基准 */
}

/* 微信右侧小尖角指针 */
.msg-me .msg-videocall-card::after {
  content: "" !important;
  position: absolute !important;
  top: 15px !important;
  right: -3.5px !important;
  width: 8px !important;
  height: 8px !important;
  background: var(--bubble-me-bg) !important;
  border-radius: 1.2px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important;
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
}

/* 微信左侧小尖角指针 */
.bubble-them-custom .msg-videocall-card::before,
.msg-them .msg-videocall-card::before {
  content: "" !important;
  position: absolute !important;
  top: 15px !important;
  left: -3.5px !important;
  width: 8px !important;
  height: 8px !important;
  background: var(--bubble-them-bg) !important;
  border-radius: 1.5px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important;
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
}

/* 📞 电话图标：尺寸适中 + 遮罩变色 */
.msg-videocall-card > div:first-child {
  width: 22px !important;
  height: 22px !important;
  min-width: 22px !important;
  min-height: 22px !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  border: none !important;
  flex-shrink: 0 !important;
  font-size: 0 !important;
  overflow: visible !important;
  display: block !important;
  background-image: none !important;
  -webkit-mask-image: var(--call-avatar-image) !important;
  mask-image: var(--call-avatar-image) !important;
  -webkit-mask-size: contain !important;
  mask-size: contain !important;
  -webkit-mask-repeat: no-repeat !important;
  mask-repeat: no-repeat !important;
  -webkit-mask-position: center !important;
  mask-position: center !important;
  background-color: currentColor !important; /* 👈 核心：100% 同步当前气泡文字颜色 */
}

.msg-videocall-card > div:first-child svg {
  display: none !important;
}

/* 我方通话：图标排在文字右侧 */
.msg-me .msg-videocall-card > div:first-child {
  order: 2;
  transform: scaleX(-1);
}

/* 文字排版容器 */
.msg-videocall-card > div:nth-child(2) {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: flex-start !important;
  max-width: none !important;
  gap: 4px !important;
  color: inherit !important;
}

.msg-videocall-card > div:nth-child(2) > div:first-child {
  letter-spacing: 0 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  margin: 0 !important;
  font-size: 0 !important;
  color: inherit !important;
}

/* 💬 提示文字（已取消 / 对方已取消 / 通话已结束 / 通话时长）字号与颜色全面联动 */
.msg-videocall-card > div:nth-child(2) > div:first-child::before {
  font-size: 15px !important;                /* 👈 核心：字号提升到 15px，和普通聊天气泡视觉完美一致 */
  font-weight: 500 !important;
  color: inherit !important;                 /* 👈 核心：完全跟随所属气泡文字色 */
  -webkit-text-fill-color: currentColor !important;
  content: "通话已结束" !important;
}

.bubble-me-custom .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.msg-me .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before {
  content: var(--call-text-me-cancel) !important;
}

.bubble-them-custom .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.msg-them .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before {
  content: var(--call-text-them-reject) !important;
}

.msg-videocall-card.connected > div:nth-child(2) > div:first-child::before {
  content: var(--call-text-connected) !important;
}

/* 隐藏无关节点 */
.msg-videocall-card > div:nth-child(2) > div:nth-child(2),
.msg-videocall-card > div:nth-child(2) > div:nth-child(2) * {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  width: 0 !important;
  height: 0 !important;
  font-size: 0 !important;
}

/* ⏱️ 通话时长数字部分（例如 00:15） */
